* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  min-height: 100%;
  background-color: #1a1a1a;
  font-family: 'TildaSans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  overflow-x: hidden;
  color: #1a1a1a;
}

.page-wrapper {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 30px 10px;
}

.phone-container {
  width: 100%;
  max-width: 430px;
  background: #ffffff;
  border-radius: 44px;
  position: relative;
  z-index: 1;
  box-shadow: 0 25px 70px rgba(0,0,0,0.5), 0 0 0 12px #2a2a2a, 0 0 0 14px #1a1a1a;
  overflow: hidden;
}

.phone-notch {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 140px;
  height: 26px;
  background: #1a1a1a;
  border-bottom-left-radius: 18px;
  border-bottom-right-radius: 18px;
  z-index: 500;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
}

.phone-notch::before {
  content: '';
  width: 48px;
  height: 4px;
  background: #2a2a2a;
  border-radius: 4px;
}

.canvas-block {
  position: relative;
  width: 100%;
  max-width: 430px;
  height: 4600px;
  margin: 0 auto;
  background: #ffffff;
  overflow: hidden;
  z-index: 2;
}

.comp {
  position: absolute;
  transform: translate(-50%, -50%);
  will-change: transform, opacity;
}

.comp img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
  user-select: none;
}

/* Animations */
.anim-init {
  opacity: 0;
  transition: opacity 0.85s cubic-bezier(0.16, 1, 0.3, 1), transform 0.85s cubic-bezier(0.16, 1, 0.3, 1);
}
.anim-fadeIn {
  opacity: 0;
}
.anim-fadeIn.animated {
  opacity: 1;
}
.anim-slideInUp {
  transform: translate(-50%, calc(-50% + 40px));
  opacity: 0;
}
.anim-slideInUp.animated {
  transform: translate(-50%, -50%);
  opacity: 1;
}
.anim-slideInDown {
  transform: translate(-50%, calc(-50% - 40px));
  opacity: 0;
}
.anim-slideInDown.animated {
  transform: translate(-50%, -50%);
  opacity: 1;
}
.anim-slideInLeft {
  transform: translate(calc(-50% - 40px), -50%);
  opacity: 0;
}
.anim-slideInLeft.animated {
  transform: translate(-50%, -50%);
  opacity: 1;
}
.anim-slideInRight {
  transform: translate(calc(-50% + 40px), -50%);
  opacity: 0;
}
.anim-slideInRight.animated {
  transform: translate(-50%, -50%);
  opacity: 1;
}
.anim-zoomIn {
  transform: translate(-50%, -50%) scale(0.85);
  opacity: 0;
}
.anim-zoomIn.animated {
  transform: translate(-50%, -50%) scale(1);
  opacity: 1;
}

/* Top Shape Banner */
.top-navy-bg {
  width: 100%;
  height: 100%;
  background: #031f45;
}

/* Hosts Navy Banner */
.hosts-navy-bg {
  width: 100%;
  height: 100%;
  background: #031f45;
  border-radius: 0px;
}

/* Marquee Ribbon */
.marquee-ribbon {
  width: 100%;
  height: 100%;
  background: #ffffff;
  overflow: hidden;
  display: flex;
  align-items: center;
  white-space: nowrap;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}
.marquee-track {
  display: inline-flex;
  gap: 20px;
  animation: marqueeRoll 20s linear infinite;
  font-family: 'KZOptima', sans-serif;
  font-size: 14px;
  color: #031f45;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
}
@keyframes marqueeRoll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Calendar Component */
.cal-wrapper {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #0d274a;
  user-select: none;
}
.cal-title {
  font-family: 'KZ_RomulC', serif;
  font-size: 16px;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 18px;
  color: #0d274a;
  font-weight: 600;
}
.cal-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  width: 100%;
  max-width: 280px;
  text-align: center;
  font-family: 'KZ_RomulC', serif;
  font-size: 12px;
  color: rgba(13, 39, 74, 0.85);
  margin-bottom: 14px;
  letter-spacing: 1px;
}
.cal-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  row-gap: 12px;
  width: 100%;
  max-width: 280px;
  text-align: center;
  font-family: 'KZ_RomulC', serif;
  font-size: 14px;
  color: #0d274a;
}
.cal-day-cell {
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.cal-day-cell.event-day {
  font-weight: bold;
  color: #ffffff;
}
.heart-marker-svg {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 36px;
  height: 36px;
  pointer-events: none;
  z-index: 1;
}
.cal-day-cell.event-day span {
  position: relative;
  z-index: 2;
  color: #ffffff;
}
.cal-time-badge {
  margin-top: 24px;
  padding: 8px 22px;
  background: #f0f4f9;
  border: 1.5px solid #031f45;
  border-radius: 8px;
  font-family: 'KZ_RomulC', serif;
  font-size: 14px;
  font-weight: 600;
  color: #031f45;
  letter-spacing: 1.5px;
}

/* Action Button: Map */
.map-action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  background: #031f45;
  color: #ffffff !important;
  font-family: 'KZ_RomulC', sans-serif;
  font-size: 16px;
  font-weight: 600;
  border-radius: 8px;
  text-decoration: none;
  letter-spacing: 1px;
  box-shadow: 0 4px 14px rgba(3, 31, 69, 0.3);
  transition: all 0.25s ease;
}
.map-action-btn:hover {
  background: #02142d;
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(3, 31, 69, 0.4);
}

/* RSVP Form Component */
.rsvp-form-container {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
  user-select: none;
}
.rsvp-option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  background: #ffffff;
  border: 1.5px solid #d1d5db;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.rsvp-option:hover {
  border-color: #031f45;
}
.rsvp-option.selected {
  border-color: #031f45;
  background: #f8fafc;
}
.rsvp-radio-circle {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid #9ca3af;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.2s ease;
}
.rsvp-option.selected .rsvp-radio-circle {
  border-color: #031f45;
}
.rsvp-radio-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: transparent;
  transition: all 0.2s ease;
}
.rsvp-option.selected .rsvp-radio-dot {
  background: #031f45;
}
.rsvp-option-text {
  font-family: 'KZOptima', sans-serif;
  font-size: 15px;
  color: #1e293b;
  font-weight: 500;
}
.rsvp-submit-button {
  width: 100%;
  height: 52px;
  background: #031f45;
  color: #ffffff;
  border: none;
  border-radius: 12px;
  font-family: 'KZOptima', sans-serif;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
  cursor: pointer;
  transition: all 0.25s ease;
  box-shadow: 0 4px 16px rgba(3, 31, 69, 0.3);
  margin-top: 4px;
}
.rsvp-submit-button:hover {
  background: #02142d;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(3, 31, 69, 0.4);
}

/* Timer card */
.timer-card-content {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-family: 'KZ_RomulC', serif;
}
.timer-badge-title {
  font-size: 18px;
  font-weight: 700;
  color: #031f45;
  letter-spacing: 2px;
  line-height: 1.3;
}
.timer-ribbon-decor {
  margin-top: 8px;
  width: 60px;
  height: 2px;
  background: #031f45;
  opacity: 0.4;
}

/* Floating audio button */
.audio-fab {
  position: fixed;
  bottom: 24px;
  left: 24px;
  z-index: 99999 !important;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px 10px 12px;
  background: #031f45;
  color: #ffffff;
  border-radius: 40px;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  font-family: 'KZOptima', sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
  transition: all 0.3s ease;
  user-select: none;
}
.audio-fab:hover {
  background: #02142d;
  transform: translateY(-2px);
  box-shadow: 0 10px 28px rgba(0,0,0,0.4);
}
.audio-fab:active {
  transform: scale(0.96);
}
.audio-icon-wrap {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
}
.audio-icon-wrap svg {
  width: 18px;
  height: 18px;
  fill: #ffffff;
}
.equalizer {
  display: none;
  align-items: center;
  gap: 3px;
  height: 16px;
}
.equalizer-bar {
  width: 3px;
  background: #ffffff;
  border-radius: 2px;
  animation: equalize 1s infinite alternate;
}
.equalizer-bar:nth-child(1) { height: 8px; animation-delay: 0s; }
.equalizer-bar:nth-child(2) { height: 16px; animation-delay: 0.2s; }
.equalizer-bar:nth-child(3) { height: 10px; animation-delay: 0.4s; }
@keyframes equalize {
  0% { height: 4px; }
  100% { height: 16px; }
}
.audio-playing .play-icon-svg {
  display: none;
}
.audio-playing .equalizer {
  display: flex;
}

/* Top banner toast */
.top-toast {
  position: fixed;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 99998 !important;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 18px;
  background: #031f45;
  color: #ffffff;
  border-radius: 30px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.25);
  font-family: 'KZOptima', sans-serif;
  font-size: 14px;
  font-weight: 500;
  user-select: none;
  width: max-content;
  max-width: calc(100% - 32px);
  animation: slideDownToast 0.5s ease;
}
@keyframes slideDownToast {
  from { transform: translateX(-50%) translateY(-60px); opacity: 0; }
  to { transform: translateX(-50%) translateY(0); opacity: 1; }
}
.toast-action-btn {
  background: rgba(255,255,255,0.2);
  color: #ffffff;
  border: none;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}
.toast-action-btn:hover {
  background: rgba(255,255,255,0.35);
}
.toast-close-btn {
  background: none;
  border: none;
  color: rgba(255,255,255,0.7);
  font-size: 16px;
  cursor: pointer;
  padding: 2px 6px;
}

/* Modals */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.65);
  backdrop-filter: blur(4px);
  z-index: 999999 !important;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.modal-backdrop.show {
  opacity: 1;
  pointer-events: auto;
}
.modal-box {
  width: 100%;
  max-width: 380px;
  background: #ffffff;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 20px 50px rgba(0,0,0,0.3);
  transform: translateY(20px) scale(0.96);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.modal-backdrop.show .modal-box {
  transform: translateY(0) scale(1);
}
.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
}
.modal-title {
  font-family: 'KZOptima', sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: #031f45;
}
.modal-close {
  background: #f1f5f9;
  border: none;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
}
.modal-close:hover {
  background: #e2e8f0;
}
.wish-form-group {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.wish-input-field {
  width: 100%;
  height: 48px;
  padding: 0 16px;
  border: 1.5px solid #cbd5e1;
  border-radius: 12px;
  font-family: 'KZOptima', sans-serif;
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s;
}
.wish-input-field:focus {
  border-color: #031f45;
}
.wish-modal-submit {
  width: 100%;
  height: 48px;
  background: #031f45;
  color: #ffffff;
  border: none;
  border-radius: 12px;
  font-family: 'KZOptima', sans-serif;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 1px;
  cursor: pointer;
  transition: background 0.2s;
}
.wish-modal-submit:hover {
  background: #02142d;
}

/* Success Toast */
.success-alert {
  position: fixed;
  top: 70px;
  left: 50%;
  transform: translateX(-50%) translateY(-20px);
  z-index: 999998 !important;
  background: #031f45;
  color: #ffffff;
  padding: 12px 24px;
  border-radius: 30px;
  box-shadow: 0 10px 30px rgba(3, 31, 69, 0.4);
  font-family: 'KZOptima', sans-serif;
  font-size: 15px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 10px;
  opacity: 0;
  pointer-events: none;
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
.success-alert.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}

/* Mobile view optimizations */
@media (max-width: 768px) {
  body {
    background-color: #ffffff;
  }
  .page-wrapper {
    padding: 0;
  }
  .phone-container {
    border-radius: 0;
    box-shadow: none;
    max-width: 100%;
  }
  .phone-notch {
    display: none;
  }
  .audio-fab {
    bottom: 16px;
    left: 16px;
    padding: 8px 14px 8px 10px;
    font-size: 14px;
  }
  .top-toast {
    width: calc(100% - 32px);
    font-size: 12px;
    padding: 8px 14px;
  }
}
